// Authored page knowledge; no model calls, remote requests or answer-key access.
const TOPICS = [
  {id: "start", phrases: ["get started", "use this", "use the page", "use the site", "how to use", "help me", "tutorial", "draw", "drawing", "canvas", "clear"],
    text: "Choose Digits for 0–9 or Letters for A–Z. Draw ONE character on the dark canvas with your mouse, finger or pen, then press ‘Read my handwriting’. Use Clear to start again.\n\nKeep the character fairly large with a little space around it. Digits and Letters recognize individual characters. Choose Words for a word or a short English line, with editable text and copy/download controls.", actions: ["workspace"]},
  {id: "upload", phrases: ["upload", "choose images", "photo", "picture", "file", "png", "jpg", "jpeg", "webp", "multiple", "batch"],
    text: "Choose the correct recognition mode, then select ‘Choose images’. You can select one or several PNG, JPG or WebP files. Each file should contain ONE character. Each image gets its own preview, prediction and scores.\n\nThe files are read locally by your browser. Blank or unreadable images show an error. The limits are 30 MB and 16 million pixels per image.", actions: ["workspace"]},
  {id: "modes", phrases: ["mode", "switch", "alphabet", "uppercase", "lowercase", "capital", "words", "sentences", "letters", "digits", "numbers"],
    text: "Digits and Letters use two separate trained CNNs. Words adds a separate pretrained handwriting reader for one word or a short English line. Digits predicts one of 0–9; Letters predicts one of A–Z. Pick the mode before drawing or selecting images.\n\nUppercase and lowercase handwriting share the same letter class, so the result does not identify case. A digit model cannot output a letter: O versus 0 depends on which mode you chose.", actions: ["workspace"]},
  {id: "pipeline", phrases: ["how does it work", "how does this work", "how does the network work", "how everything works", "how it works", "technology", "behind", "pipeline", "process", "overview"],
    text: "Here’s the journey: your drawing or image → grayscale and background removal → a centered input (28 × 28 for the MNIST-only and supplementary CNNs and Letters; 64 × 64 for the preserved residual digit CNN) → a convolutional neural network → scores for each class.\n\nPython and PyTorch trained the weights beforehand. This page runs those learned weights in JavaScript, entirely in your browser. The colored maps show actual intermediate activations. I can explain preprocessing, convolution, training or model scores in more detail.", actions: ["network", "model"]},
  {id: "preprocess", phrases: ["preprocessing", "preprocess", "normalize", "normalization", "28", "pixels", "grayscale", "background", "crop", "center", "prepared input", "model eyes"],
    text: "The image is composited onto white, converted to grayscale and compared with its border to estimate the background. Visible foreground is cropped, resized to fit a 20-pixel box for the 28 × 28 CNNs, or a 48-pixel box for the preserved 64 × 64 residual CNN, then centered in the selected model input using its center of mass.\n\nThe small preview under the scores is the actual model input. Extra marks can affect cropping and centering; this step does not reliably separate a CAPTCHA digit from crossing lines.", actions: ["workspace"]},
  {id: "architecture", phrases: ["architecture", "residual", "skip connection", "bottleneck", "cnn", "convolution", "convolutional", "filter", "pool", "relu", "dense", "layers", "neural network", "neurons"],
    text: "The MNIST-only and supplementary digit CNNs use two convolution/pooling stages, with 16 and 32 filters. The preserved residual digit CNN adds residual blocks and an average-pooling step. Each residual block adds a learned correction through a skip connection. Letters uses two convolution/pooling stages. Both models use 128 hidden activations, followed by 10 digit outputs or 26 letter outputs.\n\nConvolution searches for local patterns such as edges and curves. ReLU keeps positive responses; max pooling keeps the strongest response in each 2 × 2 area. The final layers combine patterns into class scores.", actions: ["network"]},
  {id: "training", phrases: ["train", "trained", "training", "learn", "learns", "learning", "backpropagation", "gradient", "optimizer", "adam", "loss", "epochs", "dropout", "weights"],
    text: "During training, the CNN sees labeled examples and predicts a class. Cross-entropy measures the prediction error. Backpropagation computes gradients, and AdamW updates the weights to reduce that error. Dropout helps discourage overfitting during training.\n\nValidation examples select the checkpoint; held-out test examples measure its performance afterward. The improved models received additional training with shape, stroke-width and noise variations, mixed with clean examples. The ten Desafio images were excluded from training and selection.", actions: ["model"]},
  {id: "datasets", phrases: ["dataset", "mnist", "emnist", "data split", "examples", "validation", "test set", "samples"],
    text: "Choose CNN training data below Digit model. MNIST only is the required course path: 55,000 training examples, 5,000 validation examples and 10,000 official test examples. The optional extension adds EMNIST Digits and independent synthetic CAPTCHA-style examples; report its results separately. The preserved residual CNN also used synthetic examples. It is not MNIST-only. Letters uses EMNIST Letters: 114,400 training, 10,400 validation and 20,800 official test examples.\n\nTraining changes weights. Validation selects the model. The official test split is evaluated after selection. EMNIST’s stored images are transposed into upright handwriting, and uppercase/lowercase forms share A–Z labels.", actions: ["model"]},
  {id: "scores", phrases: ["confidence", "confident", "probability", "probabilities", "softmax", "scores", "score", "percent", "percentage", "certain", "certainty"],
    text: "Softmax turns the output logits into scores that add up to 100% across the selected model’s classes. The largest score determines the prediction.\n\nA 98% model score does NOT mean a guaranteed 98% chance of being correct. These scores are not calibrated correctness probabilities, and an unfamiliar or noisy input can produce a confident mistake. Similar top scores suggest ambiguity.", actions: ["workspace"]},
  {id: "mistakes", phrases: ["wrong", "mistake", "incorrect", "misread", "error", "bad prediction", "why did", "recognize", "improve", "accuracy"],
    text: "Check the selected mode first, then inspect the prepared input preview. Tiny characters, unusual shapes, several characters together or stray marks can look very different after preprocessing. Try one clear, centered character with a little margin.\n\nThe benchmark panel reports measured clean MNIST and EMNIST Letters accuracy. These are dataset-level results, not promises for your image or CAPTCHA accuracy. Only the supplementary and preserved residual options add independently rendered CAPTCHA-style examples; the MNIST-only course model does not. I can explain likely failure modes, but I cannot determine the exact cause of an individual prediction.", actions: ["workspace", "model"]},
  {id: "challenge", phrases: ["captcha", "desafio", "challenge", "robust", "noise", "noisy", "occlusion"],
    text: "The official Desafio has ten difficult digit images with crossing lines, broken strokes and clutter. The original and first robustness models both got 2 out of 10 correct. Clean MNIST accuracy does not describe CAPTCHA accuracy.\n\nThe MNIST-only course model is the default. The optional supplementary model and preserved residual CNN are separate choices. See the selected CNN evaluation download for its own results. Historical official evaluations remain preserved; this supplementary extension has no new official challenge result. The official images are excluded from training and selection. I do not supply the challenge answer key.", actions: ["model"]},
  {id: "activations", phrases: ["feature maps", "feature map", "activations", "visualization", "colours", "colors", "heatmap", "connections", "inside the model"],
    text: "‘What happens inside?’ shows real values from the current inference: 16 first-stage feature maps, 32 second-stage maps, and 128 hidden activations. The 28px MNIST-only and supplementary digit CNNs and Letters show 14 × 14 and 7 × 7 maps. The preserved residual digit CNN shows post-residual 32 × 32 and 8 × 8 maps, with average pooling. Each map is scaled separately to make its patterns visible.\n\nThe connection list shows hidden activation × output weight products for the selected output. These are useful observations, but they are not a complete explanation of why the network chose a class.", actions: ["network"]},
  {id: "privacy", phrases: ["privacy", "private", "safe", "send", "server", "api", "offline", "internet", "javascript", "browser", "pytorch", "python"],
    text: "The site downloads static files and trained weights, then performs classification in JavaScript on your device. Drawings and selected images are not sent to a classification server. Initial loading requires access to the site; offline use after loading is not guaranteed.\n\nPython/PyTorch trained the models beforehand. SHA-256 checks verify downloaded weights, and browser outputs are tested against Python. My own replies come from built-in page knowledge; your questions are not sent to a chat API or saved between page reloads.", actions: ["model"]},
  {id: "export", phrases: ["export", "download", "save", "json", "results", "history", "collection"],
    text: "After selecting images, use ‘Export results’ above your image collection to download a JSON record. It contains each uploaded image’s prediction, scores, normalized input, recognition mode and model fingerprint.\n\nClick an image card to revisit its prediction and activations. Export covers uploaded-image records; standalone canvas predictions are not added to that collection. Reloading clears the on-page session.", actions: ["uploads"]},
  {id: "ai", phrases: ["artificial intelligence", "machine learning", "deep learning", "ai", "ml"],
    text: "Artificial intelligence is the broad field of building systems that perform tasks associated with intelligence. Machine learning learns patterns from data instead of relying only on hand-written rules. Deep learning uses neural networks with several learned layers.\n\nThe handwriting classifiers here are small deep-learning CNNs. They predict character classes from pixels; they do not understand language or read sentences. Scopedog is a separate built-in help guide, not another neural network or an LLM.", actions: ["network", "model"]},
  {id: "identity", phrases: ["who are you", "your name", "scopedog", "chatbot", "are you ai", "chatgpt", "llm", "hello", "hi", "hey"],
    text: "I’m Scopedog, your built-in Digit Lab guide. I can explain the controls, help you interpret a result and walk through the technology.\n\nI match questions to authored page knowledge rather than generate answers with an LLM. I cannot see or understand the original image, and I do not change or retrain the classifiers. Try ‘How does the network work?’ or ‘Why can a confident prediction be wrong?’", actions: ["workspace", "network"]},
];

export function answerQuestion(question, context = {}) {
  const normalize = text => text.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
  const query = ` ${normalize(question)} `;
  if (/\b(accuracy|accurate|benchmark|evaluation|percentage|percent|score)\b/.test(query) &&
      (/\b(words?|handwriting)\b/.test(query) || context.mode === "words")) {
    const metric = context.wordBenchmark;
    return {topic: "word-metrics", text: metric
      ? `The word benchmark shows ${metric.score} word accuracy for Full precision. It is 100% minus word error rate, measured on ${metric.lines} real English handwriting lines with ${metric.words} reference word tokens. Inserted, deleted and substituted words count as errors.\n\nWord error rate is ${metric.wer}; character error rate is ${metric.cer}; exact whole-line accuracy is ${metric.exact}. These are separate measurements. The word percentage is an aggregate test result, not a probability that your current transcription is correct. Digit and letter percentages use different classification tests. This line-OCR evaluation does not establish Portuguese or isolated-word accuracy.`
      : "The benchmark panel describes the measured word result and its sample size. Word accuracy is calculated as 100% minus word error rate on English handwriting lines; it is separate from digit/letter image classification accuracy and from a correctness probability for your current image.",
      actions: metric ? ["wordMetrics"] : ["workspace"]};
  }
  if (/\b(eraser|erase|erasing|undo|redo)\b/.test(query)) return {topic: "drawing-tools",
    text: "Select Eraser and drag over unwanted marks, just like a paint application. Use the Eraser size slider for finer or broader corrections, then select Pen to write again. The eraser works in Digits, Letters and Words, including on a loaded word image.\n\nUndo and Redo restore recent drawing actions, including erasing and Clear. Up to 20 actions are retained. With the canvas focused, Ctrl+Z undoes, and Ctrl+Shift+Z or Ctrl+Y redoes. Read the handwriting again after editing it; changes clear the old prediction.", actions: ["workspace"]};
  if (context.mode !== "words" && (/\b(digit model|digit reader|printed|online model|select model)\b/.test(query) ||
      context.digitReader && context.digitReader !== "local")) return {topic: "digit-readers",
    text: context.digitReader === "captcha-digits"
      ? "CAPTCHA Digits uses pretrained DdddOCR Legacy weights and scores the ten complete single-digit sequences directly from the model. It assumes exactly one digit and shows a conditional digit score, not a calibrated correctness probability. The unrestricted transcription remains available for comparison; it is not edited to produce the classified digit. No new weights were trained.\n\nThe first read downloads about 14 MB plus the runtime. Images stay on this device. Re-upload an image to compare configurations. Export records include the original transcription, ten conditional scores, weight hash and exact-single-digit decoding identity. CNN feature maps belong to the project CNN and Letters."
      : "In Digits, choose Digit Lab CNN, CAPTCHA Digits, general DdddOCR/Legacy or TrOCR using Digit model. CAPTCHA Digits assumes one digit and scores its model likelihood; general text readers accept only an original transcription containing exactly one digit. DdddOCR downloads about 54 MB or 14 MB of fixed full-precision weights. TrOCR downloads about 65 MB for Standard or 250 MB for Full precision. Downloads start only when reading; images stay on this device.\n\nGeneral OCR readers have no CNN class scores or activation maps. Switch to Digit Lab CNN to explore those. Each exported result identifies its own model and decoding configuration. No reader guarantees a correct answer.", actions: ["workspace"]};
  if (/\b(words?|sentences?|transcription|trocr|cursive)\b/.test(query) || context.mode === "words" &&
      /\b(draw|upload|model|prediction|result|copy|download|score|confidence|privacy|offline|how)\b/.test(query)) {
    if (context.mode === "words" && /\b(prediction|result)\b/.test(query)) return {
      topic: "word-result", text: context.predicted
        ? `The Words text box currently contains: ${context.predicted}\n\nThis may include your edits. Expand ‘Original model transcription’ to compare it with the unedited output. The word reader can add, omit or misread words; review the text before using it. No calibrated confidence score or CNN activation maps are available for this mode.`
        : "No word transcription is displayed yet. Write a word or a short English line, then choose ‘Read my words’. You can also choose a cropped handwriting image.", actions: ["workspace"]};
    return {topic: "words", text: "Choose Words for a whole word or a short English handwriting line. Write on the wide white canvas and press ‘Read my words’, or choose one cropped image. Review the editable text, then use Copy text or Download .txt. The original model transcription remains available separately.\n\nWords uses a separate pretrained TrOCR model. Choose Standard for a smaller 65 MB download or Full precision for about 250 MB of weights and more memory use. Both use pretrained TrOCR Small weights from Hugging Face plus the runtime from jsDelivr; this project did not train the word model. Image pixels and recognized text stay on your device. Loading needs internet access; offline availability is not guaranteed. Full pages, multiple lines and other languages are not supported. See the benchmark panel for the measured word result and its scope. The digit and letter benchmark scores apply to their own tests.", actions: ["workspace"]};
  }
  if (/\b(this prediction|current prediction|my result|this result|what did you predict)\b/.test(query)) {
    if (!context.predicted || context.predicted === "—") return {text: "There isn’t a prediction to explain yet. Draw one character and press ‘Read my handwriting’, or select an image. Then ask about your current prediction.", actions: ["workspace"]};
    return {text: `The page currently shows ${context.predicted} in ${context.mode} mode, with ${context.confidence}. This is the classifier’s output, not my own image analysis.\n\nCompare the prepared input with your original image and inspect the class scores. A high score can still be wrong; the feature maps show learned responses rather than a complete causal explanation.`, actions: ["workspace", "network"]};
  }
  let selected = null, best = 0;
  for (const topic of TOPICS) {
    let score = 0;
    for (const phrase of topic.phrases) {
      const normalized = normalize(phrase);
      if (query.includes(` ${normalized} `)) score += normalized.split(" ").length * 2;
    }
    if (score > best) {best = score; selected = topic;}
  }
  return selected ? {topic: selected.id, text: selected.text, actions: selected.actions} : {
    topic: "fallback", text: "I don’t have a reliable answer to that in my built-in guide. I can help with drawing, image uploads, model scores, preprocessing, CNNs, training, privacy and the Desafio.\n\nTry a short question such as ‘What is convolution?’ or choose a topic below.", actions: ["workspace", "network"]};
}
